import { describe, expect, it } from 'vitest';
import { renderToString } from 'react-dom/server';

function stubBrowser(hash: string, dark: boolean) {
  const store = new Map<string, string>();
  (globalThis as any).localStorage = {
    getItem: (k: string) => store.get(k) ?? null,
    setItem: (k: string, v: string) => store.set(k, v),
  };
  (globalThis as any).window = {
    location: { hash },
    matchMedia: () => ({ matches: dark, addEventListener() {}, removeEventListener() {}, addListener() {}, removeListener() {} }),
    addEventListener() {},
    removeEventListener() {},
  };
  (globalThis as any).document = undefined;
}

describe('App smoke', () => {
  it('renders every page in dark theme', async () => {
    const { App } = await import('./App');
    for (const [hash, text] of [['', 'Главная'], ['#/about', 'О приложении'], ['#/settings', 'Тема оформления'], ['#/zzz', 'Страница не найдена']]) {
      stubBrowser(hash, true);
      const html = renderToString(<App />);
      expect(html).toContain('g-root_theme_dark');
      expect(html).toContain(text);
    }
    stubBrowser('', false);
    expect(renderToString(<App />)).toContain('g-root_theme_light');
  });
});
EOF
