      expect(html).toContain(text);
      expect(html).not.toContain('g-root_theme_light');
    }
    stubBrowser('', false);
    const light = renderToString(<ThemeProvider theme="light"><App /></ThemeProvider>);
    expect(light).toContain('g-root_theme_light');
